inline constexpr size_t kPaletteCount = std::size(kPalettes);
inline constexpr size_t kTokenBase = 8;
inline constexpr size_t kTokenBaseContainer = 9;
inline constexpr size_t kTokenPrimary = 26;
inline constexpr size_t kDefaultPalette = 0;  // Catppuccin Mocha

inline constexpr SkColor IrisPaletteSeed(size_t index) {
  return SkColorSetARGB(0x01, 0x49, (index >> 8) & 0xFF, index & 0xFF);
}

// The palette a picked seed selects, or nullptr for an ordinary colour.
inline const Palette* PaletteForSeed(std::optional<SkColor> seed) {
  if (!seed || SkColorGetA(*seed) != 0x01 || SkColorGetR(*seed) != 0x49) {
    return nullptr;
  }
  const size_t index = (SkColorGetG(*seed) << 8) | SkColorGetB(*seed);
  return index < kPaletteCount ? &kPalettes[index] : nullptr;
}

